# von_bertalanffy_schnute_growth ----
## Setup ----
# The setup_default_Growth() values: L1 = 275 and L2 = 725 mm, k = 0.18 and
# SDs of 28 and 73 mm, here at reference ages 4 and 18 of ages 0 to 20.
# Arguments are on the scales the model estimates them on, with L2 as
# log(L2 - L1), as when L2 is estimated. Arguments given in `...` replace
# these, and NULL removes 1.
vonb_growth <- function(...) {
  arguments <- list(
    age = 0:20,
    log_growth_coefficient = log(0.18),
    log_length_weight_a = log(2.5e-11),
    log_length_weight_b = log(3),
    reference_ages = c(4, 18),
    length_edges = seq(0, 1500, 10),
    log_difference_mean_length_old = log(725 - 275),
    log_mean_length_young = log(275),
    log_length_at_age_sd_young = log(28),
    log_length_at_age_sd_old = log(73)
  )
  do.call(
    FIMS:::von_bertalanffy_schnute_growth,
    utils::modifyList(arguments, list(...))
  )
}
growth <- vonb_growth()
ages <- 0:20

## IO correctness ----
test_that("`von_bertalanffy_schnute_growth()` works with correct inputs", {
  #' @description Test that `von_bertalanffy_schnute_growth()` with L2 given as log(L2 - L1) gives mean length L1 at the young reference age and L2 at the old one.
  expect_equal(
    object = growth[["mean_length_at_age"]][ages %in% c(4, 18)],
    expected = c(275, 725)
  )
  #' @description Test that `von_bertalanffy_schnute_growth()` gives the same growth with L2 given as log(L2 - L1) or as log(L2).
  expect_equal(
    object = vonb_growth(
      log_difference_mean_length_old = NULL,
      log_mean_length_old = log(725)
    )[c("mean_length_at_age", "sd_length_at_age")],
    expected = growth[c("mean_length_at_age", "sd_length_at_age")]
  )
  # Between the reference ages the SD is linear in mean length, from sd1 at
  # L1 to sd2 at L2.
  is_between <- ages >= 4 & ages <= 18
  #' @description Test that `von_bertalanffy_schnute_growth()` interpolates the SD linearly in mean length between the reference ages.
  expect_equal(
    object = growth[["sd_length_at_age"]][is_between],
    expected = 28 + (73 - 28) *
      (growth[["mean_length_at_age"]][is_between] - 275) / (725 - 275)
  )
})

## Edge handling ----
test_that("`von_bertalanffy_schnute_growth()` returns correct outputs for edge cases", {
  #' @description Test that `von_bertalanffy_schnute_growth()` holds the SD at sd1 below the young reference age and at sd2 above the old one.
  expect_equal(
    object = growth[["sd_length_at_age"]][ages <= 4 | ages >= 18],
    expected = c(rep(28, 5), rep(73, 3))
  )
  #' @description Test that `von_bertalanffy_schnute_growth()` keeps mean length growing where the SD is held, below the young reference age and above the old one.
  expect_true(all(diff(growth[["mean_length_at_age"]]) > 0))

  # L2 = L1 + exp(x) is above L1 for any working value x. A difference of
  # 1e-20 is too small to change L1 = 800 in double precision, so the 2
  # lengths are then equal.
  for (length_difference in c(1e-20, 0.001, 10, 450)) {
    tiny_gap <- vonb_growth(
      age = 1:12, reference_ages = c(1, 12),
      log_mean_length_young = log(800),
      log_difference_mean_length_old = log(length_difference)
    )
    #' @description Test that `von_bertalanffy_schnute_growth()` gives L1 at the young reference age and L1 plus the difference at the old one, for differences from 1e-20 to 450.
    expect_equal(
      object = tiny_gap[["mean_length_at_age"]][c(1, 12)],
      expected = c(800, 800 + length_difference),
      tolerance = 1e-12
    )
    #' @description Test that `von_bertalanffy_schnute_growth()` gives sd1 and sd2 at the reference ages whatever the difference between L1 and L2.
    expect_equal(
      object = tiny_gap[["sd_length_at_age"]][c(1, 12)],
      expected = c(28, 73)
    )
  }
})

## Error handling ----
