# delta_method_length_sd ----
## Setup ----
# With 1 parameter's SD at a time, and no correlations, the delta-method SD
# is L(a) |d log L(a) / d log theta| sd(log theta). A large sd(log theta)
# keeps the smooth guards on the variance and the SD negligible, so SD /
# (L(a) sd(log theta)) is the gradient the function computes.
sd_log_parameter <- 1e9
log_length <- function(log_parameters, age) {
  log(FIMS:::von_bertalanffy_length_at_age(
    age, exp(log_parameters[1]), exp(log_parameters[2]),
    exp(log_parameters[3]), 1, 12
  ))
}

## IO correctness ----
test_that("`delta_method_length_sd()` works with correct inputs", {
  step <- 1e-4
  # The default k, and k (a2 - a1) near 1e-3, where 1 - exp(-k (a2 - a1))
  # has lost about 3 digits to rounding.
  for (growth_coefficient in c(0.18, 0.99e-3 / 11, 1.01e-3 / 11)) {
    log_parameters <- log(c(275, 725, growth_coefficient))
    for (age in c(5, 18)) {
      mean_length <- exp(log_length(log_parameters, age))
      for (parameter in 1:3) {
        sd_log_parameters <- replace(numeric(3), parameter, sd_log_parameter)
        delta_method_gradient <- FIMS:::delta_method_length_sd(
          age, mean_length, 275, 725, growth_coefficient, c(1, 12),
          sd_log_parameters,
          correlation = numeric(3)
        ) / (mean_length * sd_log_parameter)
        plus <- replace(
          log_parameters, parameter, log_parameters[parameter] + step
        )
        minus <- replace(
          log_parameters, parameter, log_parameters[parameter] - step
        )
        numerical <- (log_length(plus, age) - log_length(minus, age)) /
          (2 * step)
        #' @description Test that the gradient of log length at age in `delta_method_length_sd()` matches central differences for log L1, log L2 and log k, at the default k and near k = 0.
        expect_equal(
          object = delta_method_gradient,
          expected = abs(numerical),
          tolerance = 1e-6
        )
      }
    }
  }
})

